1	package sem
2	
3	import (
4		"fmt"
5		"io"
6		"os"
7		"strings"
8	
9		"github.com/entireio/entire-graph/internal/termsafe"
10	)
11	
12	func writeText(out io.Writer, result Result) {
13		styles := newTextStyles(out)
14		fmt.Fprintf(out, "%s %s\n\n", styles.title("Semantic changes"), styles.dim(result.Base+".."+result.Head))
15		if len(result.Files) == 0 {
16			fmt.Fprintln(out, styles.dim("No semantic entity changes detected."))
17			if len(result.Warnings) > 0 {
18				fmt.Fprintln(out)
19			}
20		}
21	
22		for _, file := range result.Files {
23			if file.OldPath != "" && file.OldPath != file.Path {
24				fmt.Fprintf(out, "%s %s %s", styles.file(file.OldPath), styles.dim("->"), styles.file(file.Path))
25			} else {
26				fmt.Fprint(out, styles.file(file.Path))
27			}
28			if file.Language != "" {
29				fmt.Fprintf(out, " %s", styles.dim("("+file.Language+")"))
30			}
31			fmt.Fprintln(out)
32			for _, change := range file.Changes {
33				fmt.Fprintf(out, "  %s\n", styles.describe(change))
34			}
35			fmt.Fprintln(out)
36		}
37	
38		writeTextWarnings(out, styles, result.Warnings)
39	}
40	
41	// writeTextWarnings renders result-level warnings (parse failures, ambiguous
42	// moves) so a suppressed or degraded diff is visible in the default text
43	// output rather than only in --json. It renders even when there are no file
44	// changes, since a suppressed parse failure is exactly the case where the diff
45	// would otherwise look empty.
46	func writeTextWarnings(out io.Writer, styles textStyles, warnings []ProviderWarning) {
47		if len(warnings) == 0 {
48			return
49		}
50		fmt.Fprintln(out, styles.changed("Warnings"))
51		for _, warning := range warnings {
52			fmt.Fprintf(out, "  %s %s", styles.changed("!"), styles.changed(warning.Code))
53			if warning.FilePath != "" {
54				fmt.Fprintf(out, " %s", styles.file(warning.FilePath))
55			}
56			fmt.Fprintln(out)
57			if warning.EffectOnCompleteness != "" {
58				fmt.Fprintf(out, "    %s\n", styles.dim(warning.EffectOnCompleteness))
59			}
60			if warning.Detail != "" {
61				fmt.Fprintf(out, "    %s\n", styles.dim(warning.Detail))
62			}
63		}
64	}
65	
66	func describe(change EntityChange) string {
67		dependents := dependentSuffix(change)
68		switch change.Type {
69		case "added":
70			return fmt.Sprintf("+ %s %s added", change.Kind, change.Name)
71		case "removed":
72			return fmt.Sprintf("- %s %s removed%s", change.Kind, change.Name, dependents)
73		case "renamed":
74			return fmt.Sprintf("~ %s %s renamed from %s%s", change.Kind, change.NewName, change.OldName, dependents)
75		case "moved":
76			return fmt.Sprintf("~ %s %s moved from %s%s", change.Kind, movedName(change), change.OldPath, dependents)
77		case "signature_changed":
78			return fmt.Sprintf("~ %s %s signature changed%s", change.Kind, change.Name, dependents)
79		case "body_changed":
80			return fmt.Sprintf("~ %s %s body changed%s", change.Kind, change.Name, dependents)
81		default:
82			return fmt.Sprintf("~ %s %s changed%s", change.Kind, change.Name, dependents)
83		}
84	}
85	
86	func movedName(change EntityChange) string {
87		if change.OldName != "" && change.NewName != "" {
88			return fmt.Sprintf("%s (renamed from %s)", change.NewName, change.OldName)
89		}
90		return change.Name
91	}
92	
93	func dependentSuffix(change EntityChange) string {
94		if change.Type == "added" {
95			return ""
96		}
97		if change.DependentsCount == 1 {
98			return " (1 dependent)"
99		}
100		return fmt.Sprintf(" (%d dependents)", change.DependentsCount)
101	}
102	
103	type textStyles struct {
104		color bool
105	}
106	
107	func newTextStyles(out io.Writer) textStyles {
108		return textStyles{color: shouldUseColor(out)}
109	}
110	
111	// ShouldUseColor reports whether ANSI styling is appropriate for out, applying the same
112	// NO_COLOR / FORCE_COLOR / TERM / character-device rules this renderer uses. Exported so other
113	// renderers in this binary reach the same decision instead of re-deriving it.
114	func ShouldUseColor(out io.Writer) bool {
115		return shouldUseColor(out)
116	}
117	
