	t.Setenv("ENTIRE_GRAPH_FORCE_COLOR", "")
	t.Setenv("FORCE_COLOR", "")
	t.Setenv("NO_COLOR", "")

	summary := &sem.SnapshotSummary{}
	summary.Stats.CompletenessLevel = "degraded"
